-- Generated executable query. Run with SQLite against indus_weave.db.
-- Ranks each employee once by Present late-arrival days; department is assigned at period end or last working day.
WITH late_employee AS (SELECT a.emp_id,COUNT(*) late_arrival_days,SUM(a.late_minutes) total_late_minutes FROM fact_attendance_daily a JOIN dim_date dt ON dt.date_key=a.date_key WHERE a.status='Present' AND a.late_minutes>0 AND dt.full_date BETWEEN '2026-04-01' AND '2026-09-30' GROUP BY a.emp_id), employee_period AS (SELECT l.emp_id,COALESCE(s.separation_date,'2026-09-30') department_as_of FROM late_employee l LEFT JOIN staging_separations s ON s.emp_id=l.emp_id), employee_department AS (SELECT e.emp_id,e.employee_name,d.department_name,ROW_NUMBER() OVER(PARTITION BY e.emp_id ORDER BY e.valid_from DESC,e.employee_key DESC) version_rank FROM employee_period p JOIN dim_employee e ON e.emp_id=p.emp_id AND p.department_as_of BETWEEN e.valid_from AND e.valid_to JOIN dim_department d ON d.department_key=e.department_key) SELECT l.emp_id,e.employee_name,e.department_name,l.late_arrival_days,l.total_late_minutes FROM late_employee l JOIN employee_department e ON e.emp_id=l.emp_id AND e.version_rank=1 ORDER BY l.late_arrival_days DESC,l.total_late_minutes DESC,l.emp_id LIMIT 10;
